use std::process::ExitCode;

const SHADER: &str = r"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x0: f32,
    y0: f32,
    dx: f32,
    dy: f32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) {
        return;
    }
    let cx = p.x0 + (f32(id.x) + 0.5) * p.dx;
    let cy = p.y0 + (f32(id.y) + 0.5) * p.dy;
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= p.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[id.y * p.width + id.x] = n;
}
";

struct Job {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse(path: &str) -> Result<Job, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let t: Vec<&str> = text.split_whitespace().collect();
    if t.len() < 7 {
        return Err("expected 7 values".into());
    }
    let int = |s: &str| s.parse::<u32>().map_err(|e| format!("{s}: {e}"));
    let num = |s: &str| s.parse::<f64>().map_err(|e| format!("{s}: {e}"));
    Ok(Job {
        width: int(t[0])?,
        height: int(t[1])?,
        limit: int(t[2])?,
        x_min: num(t[3])?,
        x_max: num(t[4])?,
        y_min: num(t[5])?,
        y_max: num(t[6])?,
    })
}

fn escape_times(job: &Job) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let count = u64::from(job.width) * u64::from(job.height);
    let size = count * 4;

    let dx = (job.x_max - job.x_min) / f64::from(job.width);
    let dy = (job.y_max - job.y_min) / f64::from(job.height);
    let mut params = Vec::with_capacity(32);
    for v in [job.width, job.height, job.limit, 0] {
        params.extend_from_slice(&v.to_le_bytes());
    }
    for v in [job.x_min, job.y_min, dx, dy] {
        params.extend_from_slice(&(v as f32).to_le_bytes());
    }

    let uniform = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size: 32,
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    queue.write_buffer(&uniform, 0, &params);
    let out = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let read = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: uniform.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: out.as_entire_binding() },
        ],
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(job.width.div_ceil(8), job.height.div_ceil(8), 1);
    }
    encoder.copy_buffer_to_buffer(&out, 0, &read, 0, size);
    queue.submit([encoder.finish()]);

    let slice = read.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e:?}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map: {e}"))?;
    let data = slice.get_mapped_range();
    let times = data
        .chunks_exact(4)
        .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
        .collect();
    drop(data);
    read.unmap();
    Ok(times)
}

fn run() -> Result<(), String> {
    let path = std::env::args().nth(1).ok_or("usage: escape <input>")?;
    let job = parse(&path)?;
    let times = escape_times(&job)?;

    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut sum = 0u64;
    let mut escaped = 0u64;
    for &n in &times {
        if n >= job.limit {
            inside += 1;
        } else {
            bins[(8 * u64::from(n) / u64::from(job.limit)) as usize] += 1;
            sum += u64::from(n);
            escaped += 1;
        }
    }
    let mean = if escaped == 0 { 0.0 } else { sum as f64 / escaped as f64 };
    println!("INSIDE {inside}");
    for (i, b) in bins.iter().enumerate() {
        println!("BIN {i} {b}");
    }
    println!("MEAN {mean:.3}");
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
